<script setup lang="ts">
import{onMounted,ref}from'vue';import{api}from'../api/client';
const plans=ref<any[]>([]),runs=ref<any[]>([]),leases=ref<any[]>([]),preview=ref<any>(null),selectedRun=ref<any>(null),showPlan=ref(false),showPreview=ref(false),showRun=ref(false),error=ref('');
const form=ref({lease_id:'',billing_day:1,due_days:5,advance_days:3,next_period_start:'',status:'active',items:[{kind:'water',name:'水费',amount:0,enabled:true},{kind:'electricity',name:'电费',amount:0,enabled:true},{kind:'property_fee',name:'物业费',amount:0,enabled:true},{kind:'service_fee',name:'服务费',amount:0,enabled:true}]});
function money(value:number){return `¥${((value||0)/100).toFixed(2)}`}
async function load(){const[p,r,l]=await Promise.all([api.get('/billing-plans',{params:{page:1,page_size:100}}),api.get('/billing-runs',{params:{page:1,page_size:50}}),api.get('/leases',{params:{page:1,page_size:100,status:'active'}})]);plans.value=p.data.items||[];runs.value=r.data.items||[];leases.value=l.data.items||[]}
async function save(){error.value='';try{await api.post('/billing-plans',form.value);showPlan.value=false;await load()}catch(e:any){error.value=e.response?.data?.error?.message||'保存失败'}}
async function toggle(x:any){await api.patch(`/billing-plans/${x.Plan.ID}/status`,{status:x.Plan.Status==='active'?'paused':'active'});await load()}
async function openPreview(){preview.value=(await api.post('/billing-runs/preview',{at:new Date().toISOString().slice(0,10)})).data;showPreview.value=true}
async function execute(){await api.post('/billing-runs');showPreview.value=false;await load()}
async function detail(id:string){selectedRun.value=(await api.get(`/billing-runs/${id}`)).data;showRun.value=true}
async function retry(item:any){await api.post(`/billing-runs/${selectedRun.value.run.ID}/items/${item.ID}/retry`);await detail(selectedRun.value.run.ID);await load()}
function leaseLabel(id:string){const x=leases.value.find(v=>v.ID===id);return x?`${x.PropertyID.slice(0,8)} · ${x.TenantID.slice(0,8)}`:id.slice(0,8)}
onMounted(load)
</script>
<template><div class="page"><div class="page-title"><div><h1>账单计划与任务中心</h1><p>为生效租约设置周期账单、附加收费规则，并批量预览和自动生成</p></div><div class="action-group"><button class="secondary-button" @click="openPreview">生成前预览</button><button class="primary-button" @click="showPlan=true">＋ 新建账单计划</button></div></div><div class="stat-grid"><div class="stat-card"><span>账单计划</span><strong>{{plans.length}}</strong></div><div class="stat-card"><span>启用计划</span><strong>{{plans.filter(x=>x.Plan.Status==='active').length}}</strong></div><div class="stat-card"><span>执行批次</span><strong>{{runs.length}}</strong></div><div class="stat-card"><span>失败任务</span><strong>{{runs.reduce((n,x)=>n+(x.Failed||0),0)}}</strong></div></div><section class="card"><div class="card-title"><h3>租约账单计划</h3><span>每份租约最多一份有效计划</span></div><table v-if="plans.length" class="data-table"><thead><tr><th>租约</th><th>账单日</th><th>截止规则</th><th>提前生成</th><th>下个账期</th><th>附加收费</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="x in plans" :key="x.Plan.ID"><td><strong>{{x.PropertyLabel}}</strong><div>{{x.TenantName}} · {{x.Plan.LeaseID.slice(0,8)}}</div></td><td>每月 {{x.Plan.BillingDay}} 日</td><td>账期开始后 {{x.Plan.DueDays}} 天</td><td>{{x.Plan.AdvanceDays}} 天</td><td>{{String(x.Plan.NextPeriodStart).slice(0,10)}}</td><td><span v-for="item in x.Items.filter((v:any)=>v.Enabled)" :key="item.ID" class="charge-tag">{{item.Name}} {{money(item.Amount)}}</span></td><td><span class="status-badge" :class="x.Plan.Status">{{x.Plan.Status==='active'?'启用':'暂停'}}</span></td><td><button class="secondary-button" @click="toggle(x)">{{x.Plan.Status==='active'?'暂停':'启用'}}</button></td></tr></tbody></table><div v-else class="empty-state"><b>暂无账单计划</b><span>为生效租约配置第一份自动账单计划</span></div></section><section class="card"><div class="card-title"><h3>批量执行记录</h3><span>保存成功、失败和重试结果</span></div><table v-if="runs.length" class="data-table"><thead><tr><th>执行时间</th><th>触发方式</th><th>批次状态</th><th>计划数</th><th>成功</th><th>失败</th><th>操作</th></tr></thead><tbody><tr v-for="x in runs" :key="x.ID"><td>{{String(x.StartedAt).replace('T',' ').slice(0,19)}}</td><td>{{x.TriggerType==='scheduled'?'自动调度':'手动执行'}}</td><td><span class="status-badge" :class="x.Status">{{x.Status}}</span></td><td>{{x.Total}}</td><td>{{x.Succeeded}}</td><td>{{x.Failed}}</td><td><button class="secondary-button" @click="detail(x.ID)">查看明细</button></td></tr></tbody></table><div v-else class="empty-state"><b>暂无执行记录</b><span>预览确认后可手动运行，系统也会定时扫描</span></div></section><div v-if="showPlan" class="modal-mask" @click.self="showPlan=false"><div class="modal billing-modal"><div class="modal-header"><div><h3>新建账单计划</h3><small>租金来自租约，附加费用按收费项目合计</small></div><button class="close-button" @click="showPlan=false">×</button></div><div class="modal-body"><div class="form-grid"><label class="full"><span>生效租约 *</span><select v-model="form.lease_id"><option value="">请选择租约</option><option v-for="x in leases" :key="x.ID" :value="x.ID">{{leaseLabel(x.ID)}} · 月租 {{money(x.MonthlyRent)}}</option></select></label><label><span>每月账单日</span><input v-model.number="form.billing_day" type="number" min="1" max="28"></label><label><span>缴费截止天数</span><input v-model.number="form.due_days" type="number" min="0" max="60"></label><label><span>提前生成天数</span><input v-model.number="form.advance_days" type="number" min="0" max="28"></label><label><span>下个账期开始日</span><input v-model="form.next_period_start" type="date"></label></div><div class="charge-editor"><h4>附加收费规则</h4><div v-for="item in form.items" :key="item.kind" class="charge-row"><input v-model="item.name"><input v-model.number="item.amount" type="number" min="0" placeholder="金额（分）"><label><input v-model="item.enabled" type="checkbox"> 启用</label></div></div><p v-if="error" class="form-error">{{error}}</p></div><div class="modal-footer"><button class="secondary-button" @click="showPlan=false">取消</button><button class="primary-button" :disabled="!form.lease_id" @click="save">保存计划</button></div></div></div><div v-if="showPreview" class="modal-mask" @click.self="showPreview=false"><div class="modal billing-modal"><div class="modal-header"><div><h3>批量生成预览</h3><small>本次预计生成 {{preview?.Count||0}} 张账单，总金额 {{money(preview?.TotalAmount)}}</small></div><button class="close-button" @click="showPreview=false">×</button></div><div class="modal-body"><table class="data-table"><thead><tr><th>房源/租客</th><th>账期</th><th>租金</th><th>附加费</th><th>合计</th></tr></thead><tbody><tr v-for="x in preview?.Items||[]" :key="x.PlanID"><td><strong>{{x.PropertyLabel}}</strong><div>{{x.TenantName}}</div></td><td>{{String(x.PeriodStart).slice(0,10)}} 至 {{String(x.PeriodEnd).slice(0,10)}}</td><td>{{money(x.RentAmount)}}</td><td>{{money(x.AdditionalAmount)}}</td><td><strong>{{money(x.TotalAmount)}}</strong></td></tr></tbody></table><div v-if="!preview?.Count" class="empty-state"><b>当前没有到期计划</b><span>账单日和提前生成天数尚未到达</span></div></div><div class="modal-footer"><button class="secondary-button" @click="showPreview=false">关闭</button><button class="primary-button" :disabled="!preview?.Count" @click="execute">确认批量生成</button></div></div></div><div v-if="showRun" class="modal-mask" @click.self="showRun=false"><div class="modal billing-modal"><div class="modal-header"><div><h3>批次执行明细</h3><small>成功 {{selectedRun?.run?.Succeeded||0}}，失败 {{selectedRun?.run?.Failed||0}}</small></div><button class="close-button" @click="showRun=false">×</button></div><div class="modal-body"><table class="data-table"><thead><tr><th>租约</th><th>账期</th><th>金额</th><th>状态</th><th>错误原因</th><th>操作</th></tr></thead><tbody><tr v-for="x in selectedRun?.items||[]" :key="x.ID"><td>{{x.LeaseID.slice(0,8)}}</td><td>{{String(x.PeriodStart).slice(0,10)}}</td><td>{{money(x.Amount)}}</td><td>{{x.Status}}</td><td>{{x.ErrorMessage||'-'}}</td><td><button v-if="x.Status==='failed'" class="primary-button" @click="retry(x)">重新执行</button></td></tr></tbody></table></div></div></div></div></template>
<style scoped>.charge-tag{display:inline-block;padding:3px 7px;background:#eef7f4;color:#168a72;border-radius:8px;font-size:10px;margin:2px}.billing-modal{width:min(920px,94vw)}.charge-editor{margin-top:20px;padding:15px;background:#f7f9fb;border-radius:12px}.charge-editor h4{margin:0 0 12px}.charge-row{display:grid;grid-template-columns:1fr 160px 90px;gap:10px;margin-top:9px;align-items:center}.charge-row label{display:flex;align-items:center;gap:6px;font-size:12px}</style>
